7	/// AD-5 — the one interceptor that owns every outgoing request's headers.
8	/// `apikey` is sent on every call. `Authorization` carries the anon key only
9	/// on the three `security: []` operations (signup, login, refresh) and the
10	/// user's access token on every other (`bearerAuth`) operation.
11	class HeaderInterceptor extends Interceptor {
12	  HeaderInterceptor({
13	    required String anonKey,
14	    required AccessTokenProvider accessTokenProvider,
15	  })  : _anonKey = anonKey,
16	        _accessTokenProvider = accessTokenProvider;
17	
18	  /// The three operations with `security: []` in the contract — the only
19	  /// ones that ever send the anon key as the bearer token.
20	  static const anonKeyOnlyFunctions = {
21	    'auth-signup',
22	    'auth-login',
23	    'auth-refresh',
24	  };
25	
26	  final String _anonKey;
27	  final AccessTokenProvider _accessTokenProvider;
28	
29	  @override
30	  void onRequest(
31	    RequestOptions options,
32	    RequestInterceptorHandler handler,
33	  ) async {
34	    options.headers['apikey'] = _anonKey;
35	
36	    String function;
37	    try {
38	      function = functionNameOf(options.path);
39	    } catch (error) {
40	      // A malformed `options.path` must never crash/hang the pipeline (an
41	      // uncaught throw here, before `handler.next` is called, would leave
42	      // the request unresolved forever) — proceed as if the function were
43	      // unrecognized rather than let it propagate.
44	      debugPrint(
45	        'HeaderInterceptor: functionNameOf failed ($error) for path '
46	        '"${options.path}" — treating as unrecognized.',
47	      );
48	      function = '';
49	    }
50	    if (anonKeyOnlyFunctions.contains(function)) {
51	      options.headers['Authorization'] = 'Bearer $_anonKey';
52	    } else {
53	      String? userToken;
54	      try {
55	        userToken = await _accessTokenProvider.readAccessToken();
56	      } catch (error) {
57	        // A thrown platform exception from the native secure-storage
58	        // channel must never crash the request pipeline — proceed as if no
59	        // token were found rather than let it propagate uncaught. Logged so
60	        // a genuine bug in a future AccessTokenProvider implementation
61	        // isn't silently invisible.
62	        debugPrint(
63	          'HeaderInterceptor: readAccessToken failed ($error) — proceeding '
64	          'without an Authorization header.',
65	        );
66	        userToken = null;
67	      }
68	      if (userToken != null) {
69	        options.headers['Authorization'] = 'Bearer $userToken';
70	      }
71	    }
72	
73	    handler.next(options);
74	  }
75	
76	  /// The `x-cerne-function` name is always the first path segment of a URL
77	  /// built by `UrlBuilder` (whether [path] is the full absolute URL
78	  /// `ApiClient` sends to `dio`, or a bare `/function/...` path) — pure, so
79	  /// it's independently testable.
80	  static String functionNameOf(String path) {
81	    final segments = Uri.parse(path).pathSegments;
82	    return segments.isNotEmpty ? segments.first : '';
83	  }
84	}
